const _caches = new WeakMap();   // per THREE (the game has one; the tests' stand-in is another)
const CM = 0.01;   // the data is in centimetres

function b64(s, Type) {
  const bin = typeof atob === 'function' ? atob(s) : Buffer.from(s, 'base64').toString('binary');
  const u8 = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return new Type(u8.buffer, 0, u8.byteLength / Type.BYTES_PER_ELEMENT);
}

// A part as plain arrays: { p: Float32Array (cm), c: Float32Array 0..1, i: Uint32Array }
function unpack(part) {
  const v = b64(part.v, Int16Array), c = b64(part.c, Uint8Array), f = b64(part.f, Uint16Array), nn = b64(part.n, Int8Array);
  const n = new Float32Array(nn.length); for (let k = 0; k < nn.length; k += 3) { const l = Math.hypot(nn[k], nn[k + 1], nn[k + 2]) || 1; n[k] = nn[k] / l; n[k + 1] = nn[k + 1] / l; n[k + 2] = nn[k + 2] / l; }
  const p = new Float32Array(v.length); for (let k = 0; k < v.length; k++) p[k] = v[k] / 100;
  const cc = new Float32Array(c.length); for (let k = 0; k < c.length; k++) cc[k] = c[k] / 255;
  return { p, n, c: cc, i: Uint32Array.from(f) };
}

// Plain parts made here (eyes, plugs, horns, fangs, ...): a THREE geometry -> the same arrays, transformed.
function fromGeo(geo, m, rgb) {
  const g = geo.index ? geo : geo;
  if (!g.attributes.normal) g.computeVertexNormals();
  const P = g.attributes.position, N = g.attributes.normal, n = P.count;
  const p = new Float32Array(n * 3), c = new Float32Array(n * 3), nr = new Float32Array(n * 3);
  const e = m ? m.elements : null;
  const nm = m ? new m.constructor().copy(m).invert().transpose().elements : null;
  for (let k = 0; k < n; k++) {
    const x = P.getX(k), y = P.getY(k), z = P.getZ(k);
    if (e) {
      p[k * 3] = e[0] * x + e[4] * y + e[8] * z + e[12];
      p[k * 3 + 1] = e[1] * x + e[5] * y + e[9] * z + e[13];
      p[k * 3 + 2] = e[2] * x + e[6] * y + e[10] * z + e[14];
    } else { p[k * 3] = x; p[k * 3 + 1] = y; p[k * 3 + 2] = z; }
    let nx = N.getX(k), ny = N.getY(k), nz = N.getZ(k);
    if (nm) { const ax = nm[0] * nx + nm[4] * ny + nm[8] * nz, ay = nm[1] * nx + nm[5] * ny + nm[9] * nz, az = nm[2] * nx + nm[6] * ny + nm[10] * nz; nx = ax; ny = ay; nz = az; }
    const nl = Math.hypot(nx, ny, nz) || 1; nr[k * 3] = nx / nl; nr[k * 3 + 1] = ny / nl; nr[k * 3 + 2] = nz / nl;
    const col = typeof rgb === 'function' ? rgb(p[k * 3], p[k * 3 + 1], p[k * 3 + 2]) : (rgb || [1, 1, 1]);
    c[k * 3] = col[0]; c[k * 3 + 1] = col[1]; c[k * 3 + 2] = col[2];
  }
  let idx;
  if (g.index) idx = Uint32Array.from(g.index.array);
  else { idx = new Uint32Array(n); for (let k = 0; k < n; k++) idx[k] = k; }
  geo.dispose && geo.dispose();
  return { p, n: nr, c, i: idx };
}

function xform(part, fn) {
  const p = part.p.slice();
  const v = [0, 0, 0];
  for (let k = 0; k < p.length; k += 3) { v[0] = p[k]; v[1] = p[k + 1]; v[2] = p[k + 2]; fn(v); p[k] = v[0]; p[k + 1] = v[1]; p[k + 2] = v[2]; }
  return { p, n: part.n, c: part.c, i: part.i };
}

// Merge parts into one BufferGeometry, centimetres -> metres, shifted by (0, dy, dz).
function merge(THREE, parts, dy, dz, colour = true, S = 1) {
  parts = parts.filter(Boolean);
  if (!parts.length) return null;
  let nv = 0, ni = 0;
  for (const q of parts) { nv += q.p.length / 3; ni += q.i.length; }
  const pos = new Float32Array(nv * 3), nrm = new Float32Array(nv * 3), col = colour ? new Float32Array(nv * 3) : null;
  const idx = nv > 65535 ? new Uint32Array(ni) : new Uint16Array(ni);
  let ov = 0, oi = 0;
  for (const q of parts) {
    for (let k = 0; k < q.p.length; k += 3) {
      pos[ov * 3 + k] = q.p[k] * CM * S; pos[ov * 3 + k + 1] = (q.p[k + 1] + dy) * CM * S; pos[ov * 3 + k + 2] = (q.p[k + 2] + dz) * CM * S;
    }
    nrm.set(q.n, ov * 3);
    if (col) col.set(q.c, ov * 3);
    for (let k = 0; k < q.i.length; k++) idx[oi + k] = q.i[k] + ov;
    ov += q.p.length / 3; oi += q.i.length;
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('normal', new THREE.BufferAttribute(nrm, 3));
  if (col) geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
  geo.setIndex(new THREE.BufferAttribute(idx, 1));
  geo.computeBoundingBox(); geo.computeBoundingSphere();
  return geo;
}

const VARIANT = { brute: 'heavy', colossus: 'heavy', leaper: 'long', spider: 'chitin' };
const JAW_OPEN = { screamer: 0.5, spitter: 0.3 };   // radians, about the condyles (the old box jaw's angles)

// a tapered tube along points (cm), radius r0 -> r1; returns a part. Built here (Catmull-Rom through the points,
// parallel-transported rings) so it needs nothing from THREE's curve classes.
function tube(THREE, pts, r0, r1, radial, rgb) {
  const segs = Math.max(2, pts.length + 1), n = pts.length;
  const at = (u) => {   // Catmull-Rom through pts, u in 0..1
    const f = Math.min(n - 1 - 1e-9, Math.max(0, u * (n - 1))), k = Math.floor(f), t = f - k;
    const P0 = pts[Math.max(0, k - 1)], P1 = pts[k], P2 = pts[Math.min(n - 1, k + 1)], P3 = pts[Math.min(n - 1, k + 2)];
    const t2 = t * t, t3 = t2 * t, o = [0, 0, 0];
    for (let d = 0; d < 3; d++) o[d] = 0.5 * (2 * P1[d] + (-P0[d] + P2[d]) * t + (2 * P0[d] - 5 * P1[d] + 4 * P2[d] - P3[d]) * t2 + (-P0[d] + 3 * P1[d] - 3 * P2[d] + P3[d]) * t3);
    return o;
  };
  const norm = (v) => { const l = Math.hypot(v[0], v[1], v[2]) || 1; return [v[0] / l, v[1] / l, v[2] / l]; };
  const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
  const C = [], Tn = [];
  for (let s = 0; s <= segs; s++) C.push(at(s / segs));
  for (let s = 0; s <= segs; s++) { const a = C[Math.max(0, s - 1)], b = C[Math.min(segs, s + 1)]; Tn.push(norm([b[0] - a[0], b[1] - a[1], b[2] - a[2]])); }
  let N = Math.abs(Tn[0][1]) < 0.9 ? [0, 1, 0] : [1, 0, 0];
  N = norm(cross(cross(Tn[0], N), Tn[0]));
  const ring = radial + 1, nv = (segs + 1) * ring;
  const p = new Float32Array(nv * 3), nr = new Float32Array(nv * 3), c = new Float32Array(nv * 3);
  for (let s = 0; s <= segs; s++) {
    if (s) { const B = cross(Tn[s], N); N = norm(cross(B, Tn[s])); }   // carry the frame along
    const Bn = cross(Tn[s], N), r = r0 + (r1 - r0) * (s / segs);
    for (let k = 0; k < ring; k++) {
      const a = (k / radial) * Math.PI * 2, ca = Math.cos(a), sa = Math.sin(a), vi = (s * ring + k) * 3;
      const d = [N[0] * ca + Bn[0] * sa, N[1] * ca + Bn[1] * sa, N[2] * ca + Bn[2] * sa];
      for (let q = 0; q < 3; q++) { p[vi + q] = C[s][q] + d[q] * r; nr[vi + q] = d[q]; }
      const col = typeof rgb === 'function' ? rgb(p[vi], p[vi + 1], p[vi + 2]) : (rgb || [1, 1, 1]);
      c[vi] = col[0]; c[vi + 1] = col[1]; c[vi + 2] = col[2];
    }
  }
  const idx = new Uint32Array(segs * radial * 6);
  let o = 0;
  for (let s = 0; s < segs; s++) for (let k = 0; k < radial; k++) {
    const a = s * ring + k, b = (s + 1) * ring + k, c2 = (s + 1) * ring + k + 1, d = s * ring + k + 1;
    idx[o++] = a; idx[o++] = d; idx[o++] = b; idx[o++] = b; idx[o++] = d; idx[o++] = c2;
  }
  return { p, n: nr, c, i: idx };
}

function ellipsoids(THREE, list, ws, hs, rgb) {
  const parts = [];
  const m = new THREE.Matrix4();
  for (const e of list) {
    m.makeScale(e[3], e[4] ?? e[3], e[5] ?? e[3]).setPosition(e[0], e[1], e[2]);
    parts.push(fromGeo(new THREE.SphereGeometry(1, ws, hs), m, rgb));
  }
  return parts;
}

function rotJaw(part, pivot, a) {
  if (!a) return part;
  const c = Math.cos(a), s = Math.sin(a);
  const out = xform(part, (v) => {
    const y = v[1] - pivot[1], z = v[2] - pivot[2];
    v[1] = pivot[1] + y * c - z * s; v[2] = pivot[2] + y * s + z * c;
  });
  const n = part.n.slice();
  for (let k = 0; k < n.length; k += 3) { const y = n[k + 1], z = n[k + 2]; n[k + 1] = y * c - z * s; n[k + 2] = y * s + z * c; }
  out.n = n;
  return out;
}

function boneTone(x, y, z) {   // for bone parts made here: a mid aged tone, darker toward the tip's base
  const n = 0.86 + 0.08 * Math.sin(x * 3.1 + y * 2.3 + z * 1.7);
  return [n, n * 0.95, n * 0.84];
}

export function skullDropParts(THREE, kind, L = {}) {
  const key = kind + (L.long ? ':long' : '') + (L.drool ? ':drool' : '') + (L.gape ? ':gape' : '');
  let _cache = _caches.get(THREE);
  if (!_cache) _caches.set(THREE, _cache = new Map());
  let out = _cache.get(key);
  if (out) return out;
  const variant = VARIANT[kind] || (L.long ? 'long' : 'human');
  const D = DATA[variant];
  const bone = [unpack(D.bone)], dark = [], eye = [], extras = [];
  const pivot = D.pivot;
  // centre on x/z, chin on the floor: the data's chin is at y ~ 0 and its middle at z ~ -1
  const dz = variant === 'chitin' ? -0.4 : (variant === 'long' ? 2.4 : 1.0), dy = variant === 'chitin' ? 0.0 : 0.0;
  const S = variant === 'chitin' ? 1.3 : 1;   // the spider's head shell: a big creature's, 16 cm across
  const jawA = L.gape ? JAW_OPEN.screamer : (L.drool ? JAW_OPEN.spitter : 0.035);
  if (D.jaw) bone.push(rotJaw(unpack(D.jaw), pivot, jawA));
  if (D.fang) bone.push(unpack(D.fang));
  // the eyes: an ember deep in each socket (the spider: its whole cluster)
  for (const e of D.eyes) eye.push(...ellipsoids(THREE, [[e[0], e[1], e[2], e[3]]], 6, 4));
  // dark plugs deep in the holes, so the flash never lights the back of a socket
  for (const q of D.plugs.slice(0, 3)) dark.push(...ellipsoids(THREE, [q], 6, 3));
  if (L.gape || L.drool) dark.push(...ellipsoids(THREE, D.plugs.slice(3), 6, 4));   // the throat, seen only with the jaw open
  const ext = (mat, part) => { let x = extras.find((e) => e.mat === mat); if (!x) extras.push(x = { mat, parts: [] }); x.parts.push(part); };

  if (L.fangs && variant !== 'chitin') {   // the feral: long curved canines over the upper ones
    for (const sx of [-1, 1]) {
      const x = sx * 1.95, z = 8.1 - 0.38 * x * x;
      bone.push(tube(THREE, [[x, 5.8, z - 0.05], [x * 1.02, 4.7, z + 0.2], [x * 1.04, 3.6, z + 0.75], [x * 1.0, 2.7, z + 1.25]], 0.4, 0.06, 4, boneTone));
    }
  }
  if (L.drool) {   // acid strings from the upper teeth to the slack jaw
    for (const [x, len, r] of [[1.1, 4.8, 0.2], [-1.6, 3.6, 0.17], [2.4, 4.2, 0.15]]) {
      const z = 8.15 - 0.38 * x * x;
      ext('acid', tube(THREE, [[x, 4.8, z], [x * 1.04, 4.8 - len * 0.45, z + 0.35], [x * 1.08, 4.8 - len, z + 0.2]], r, r * 0.55, 4));
    }
  }
  if (L.weed) {   // drowned: weed strands draped over the crown and down the side, a clump in a socket
    const strands = DATA.human.weed;   // laid on the bone offline (review/CJ-2/skull-gen.py)
    for (const s of strands) ext('weed', tube(THREE, s, 0.6, 0.32, 3));
  }
  if (L.helmet) {   // the soldier: a steel helmet sat on the crown, a little askew, the chin strap hanging
    const g = new THREE.SphereGeometry(1, 12, 5, 0, Math.PI * 2, 0, Math.PI * 0.56);
    const P = g.attributes.position;
    for (let k = 0; k < P.count; k++) {
      let x = P.getX(k), y = P.getY(k), z = P.getZ(k);
      const rim = 1 - Math.min(1, Math.max(0, (y + 0.02) / 0.32));   // 1 at the rim, 0 above
      x *= 8.15 * (1 + 0.1 * rim); z *= 11.0 * (1 + 0.1 * rim); y = y * 8.2 - rim * 0.5;
      P.setXYZ(k, x, y, z);
    }
    const m = new THREE.Matrix4().makeRotationX(-0.16).premultiply(new THREE.Matrix4().makeRotationZ(0.1));
    m.premultiply(new THREE.Matrix4().makeTranslation(0.15, 13.6, -1.3));
    ext('olive', fromGeo(g, m));
    for (const sx of [-1, 1]) ext('olive', tube(THREE, [[sx * 7.6, 13.6, -0.6], [sx * 7.4, 11.4, 0.4], [sx * 6.9, 9.6, 1.6]], 0.16, 0.16, 3));
  }
  if (L.horns) {   // the demon: ridged horns from the temples, sweeping out, back and up
    for (const sx of [-1, 1]) ext('horn', tube(THREE, [[sx * 4.6, 18.4, 4.2], [sx * 7.4, 20.4, 3.0], [sx * 9.4, 23.6, 0.2], [sx * 9.6, 27.4, -2.4], [sx * 8.4, 30.0, -3.6]], 1.6, 0.12, 5));
  }
  if (L.fuse) {   // the bomber: a fuse cord in a hole in the crown, its spark at the end
    dark.push(tube(THREE, [[1.4, 19.8, -1.0], [2.0, 22.0, -1.4], [3.2, 23.8, -1.0], [4.6, 24.6, -0.2]], 0.32, 0.26, 5));
    ext('glow', ...ellipsoids(THREE, [[4.75, 24.7, -0.1, 0.75]], 6, 4));
  }
  if (!L.crack && !L.helmet && !L.weed && variant !== 'chitin') {   // the cracks: hairline dark cords laid in the bone (the helmet and the weed cover the crown's)
    for (const path of D.cracks) dark.push(tube(THREE, path.map((q) => scaleIn(q, 0.02)), 0.075, 0.05, 3));
  }
  if (variant === 'chitin') for (const path of D.cracks) dark.push(tube(THREE, path, 0.08, 0.05, 3));
  if (L.crack) {   // the colossus: fire in its cracks (strips sunk in the grooves, below the bone's surface)
    for (const path of D.cracks) ext('glow', tube(THREE, path.map((q) => scaleIn(q, 0.06)), 0.17, 0.12, 3));
  }
  out = {
    bone: merge(THREE, bone, dy, dz, true, S),
    dark: merge(THREE, dark, dy, dz, true, S),
    eye: merge(THREE, eye, dy, dz, true, S),
    extras: extras.map((e) => ({ mat: e.mat, geo: merge(THREE, e.parts, dy, dz, true, S) })),
    variant,
  };
  const tri = (g) => (g ? g.index.count / 3 : 0);
  out.tris = tri(out.bone) + tri(out.dark) + tri(out.eye) + out.extras.reduce((a, e) => a + tri(e.geo), 0);
  _cache.set(key, out);
  return out;
}

// pull a point on the cranium toward its centre by d cm (so the glow sits in the groove, under the surface)
function scaleIn(q, d) {
  const c = [0, 13.7, -1.2];
  const v = [q[0] - c[0], q[1] - c[1], q[2] - c[2]], l = Math.hypot(v[0], v[1], v[2]) || 1;
  return [q[0] - v[0] / l * d, q[1] - v[1] / l * d, q[2] - v[2] / l * d];
}

export const SKULL_VARIANTS = () => Object.keys(DATA);

// CJ-3 (CH-3 #13): the same skull as ONE geometry with every colour baked in (the bone's tint times its age colours,
// the dark holes, the eyes (a 'skullGlow' attribute marks them), the kind's extras), for a still display: one draw.
// L.tint / L.eye as SKULL_LOOK's. Real size, as skullDropParts.
const SPEC_COL = { dark: 0x0e0c0a, olive: 0x4a5540, horn: 0x2a1410, weed: 0x2f6b3a, glow: 0xff7a1a, acid: 0xb8e030 };
export function skullDropSpecimen(THREE, kind, L = {}) {
  let _cache = _caches.get(THREE);
  if (!_cache) _caches.set(THREE, _cache = new Map());
  const key = 'specimen:' + kind;
  let geo = _cache.get(key);
  if (geo) return geo;
  const P = skullDropParts(THREE, kind, L);
  const bone = new THREE.Color(0xe8e0cc).lerp(new THREE.Color(L.tint ?? 0xd4c4a8), 0.42);
  const list = [[P.bone, bone, true], [P.dark, new THREE.Color(SPEC_COL.dark)], [P.eye, new THREE.Color(L.eye ?? 0x88ff44), false, 1],
    ...P.extras.map((e) => [e.geo, new THREE.Color(SPEC_COL[e.mat] ?? 0x808080)])].filter((x) => x[0]);
  let nv = 0, ni = 0;
  for (const [g] of list) { nv += g.attributes.position.count; ni += g.index.count; }
  const pos = new Float32Array(nv * 3), nrm = new Float32Array(nv * 3), col = new Float32Array(nv * 3), glow = new Float32Array(nv), idx = new Uint32Array(ni);
  let ov = 0, oi = 0;
  for (const [g, c, mul, gl] of list) {
    if (gl) glow.fill(gl, ov, ov + g.attributes.position.count);
    const n = g.attributes.position.count, C = g.attributes.color;
    pos.set(g.attributes.position.array, ov * 3); nrm.set(g.attributes.normal.array, ov * 3);
    for (let k = 0; k < n; k++) {
      const m = mul && C ? [C.getX(k), C.getY(k), C.getZ(k)] : [1, 1, 1];
      col[(ov + k) * 3] = c.r * m[0]; col[(ov + k) * 3 + 1] = c.g * m[1]; col[(ov + k) * 3 + 2] = c.b * m[2];
    }
    const I = g.index.array; for (let k = 0; k < I.length; k++) idx[oi + k] = I[k] + ov;
    ov += n; oi += I.length;
  }
  geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('normal', new THREE.BufferAttribute(nrm, 3));
  geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
  geo.setAttribute('skullGlow', new THREE.BufferAttribute(glow, 1));   // 1 on the eyes: a node material can light them (emissiveNode)
  geo.setIndex(new THREE.BufferAttribute(nv > 65535 ? idx : Uint16Array.from(idx), 1));
  geo.computeBoundingBox(); geo.computeBoundingSphere();
  _cache.set(key, geo);
  return geo;
}
